    // User Tutorial
    "tutorial.stepAriaLabel": "Langkah Tutorial",
    "tutorial.stepLabelPrefix": "Langkah",
    "tutorial.culturalHighlightLabel": "Konteks Sejarah & Budaya:",
    "tutorial.interactiveExerciseLabel": "Latihan Interaktif:",
    "tutorial.boardPreviewTitle": "Simulasi Medan Pertempuran 2-Baris",
    "tutorial.botFrontRow": "Baris Depan Lawan (Bot)",
    "tutorial.playerFrontRow": "Baris Depan Ksatria",
    "tutorial.playerBackRow": "Baris Belakang Ksatria",
    "tutorial.waditraHand": "Tangan Waditra",
    "tutorial.step1.title": "1. Formasi Taktis 2-Baris & Kartu Lawan Tertutup",
    "tutorial.step1.culturalHighlight": "Terinspirasi tata gelar pasukan Wilwatikta (Majapahit) dan Pakuan (Pajajaran) yang membagi barisan tempur utama dan barisan cadangan.",
    "tutorial.step1.ruleExplanation": "Setiap pemain menyusun Deck berisi 10 Karakter dan 0 sampai 10 Instrumen. Saat laga dimulai, 5 Karakter ditempatkan di papan: 2 di Baris Depan (Front Row) dan 3 di Baris Kedua (Second Row), sementara 5 sisanya di Deck Cadangan. Seluruh kartu lawan di papan dimulai dalam posisi tertutup (Face-Down).",
    "tutorial.step1.interactiveTaskPrompt": "Klik tombol simulasi di bawah untuk menempatkan 5 Karakter awal di Baris Depan dan Baris Kedua.",
    "tutorial.step1.actionButtonLabel": "Simulasikan Penempatan 2-Baris",
    "tutorial.step1.outcomeFeedback": "Berhasil! Raden Wijaya dan Gajah Mada kini menjaga Baris Depan, sementara Hayam Wuruk, Tribhuwana, dan Mpu Prapanca siaga di Baris Kedua.",
    "tutorial.step2.title": "2. Lempar Dadu, Draw Instrumen & Batas Tangan 6 Kartu",
    "tutorial.step2.culturalHighlight": "Waditra (instrumen musik tradisional) berfungsi sebagai isyarat komando rahasia di medan laga.",
    "tutorial.step2.ruleExplanation": "Di awal pertandingan, kedua pemain melempar dadu 3D untuk menentukan giliran pertama dan menerima 3 kartu Instrumen awal di tangan. Setiap awal giliran, pemain mengambil 1 kartu Instrumen. Batas maksimal tangan adalah 6 kartu: jika tangan penuh, kartu baru langsung masuk ke Discard Pile. Jika Deck Instrumen habis, Discard Pile dikocok ulang otomatis.",
    "tutorial.step2.interactiveTaskPrompt": "Simulasikan pengambilan kartu Instrumen pada awal giliran.",
    "tutorial.step2.actionButtonLabel": "Ambil Kartu Instrumen (Draw)",
    "tutorial.step2.outcomeFeedback": "Kartu Instrumen Kendang berhasil diambil ke tangan rahasia Anda (4/6 kartu di tangan)!",
    "tutorial.step3.title": "3. Efek Instrumen & Bonus Sinergi Afinitas (+100 Stat)",
    "tutorial.step3.culturalHighlight": "Setiap instrumen Nusantara memiliki kedekatan budaya dengan peran tertentu (Pemimpin, Prajurit, Pemuka, Utusan, atau Perajin).",
    "tutorial.step3.ruleExplanation": "Instrumen dapat dipasangkan ke Karakter mana saja di papan untuk efek fleksibel. Namun, jika Peran (Utama/Sekunder) dan Gender Karakter cocok dengan afinitas Instrumen, Karakter tersebut mendapatkan Bonus Sinergi +100 Stat tambahan!",
    "tutorial.step3.interactiveTaskPrompt": "Pasangkan instrumen Padahi (+300 ATK, Afinitas Prajurit) pada Gajah Mada (Peran: Prajurit).",
    "tutorial.step3.actionButtonLabel": "Aktifkan Padahi pada Gajah Mada",
    "tutorial.step3.outcomeFeedback": "Sinergi Aktif! Gajah Mada mendapat +300 ATK dasar + 100 Bonus Sinergi Prajurit = +400 ATK (Total ATK menjadi 1900)!",
    "tutorial.step4.title": "4. Serangan Tembus Pertahanan (ATK > DEF)",
    "tutorial.step4.culturalHighlight": "Hanya Karakter di Baris Depan (Front Row) yang dapat mendeklarasikan serangan maupun diserang.",
    "tutorial.step4.ruleExplanation": "Saat Karakter A di Baris Depan menyerang Karakter B di Baris Depan lawan, kartu lawan yang tertutup akan terbuka. Jika Attack Penyerang lebih besar dari Defence Bertahan (ATK A > DEF B), maka Karakter B gugur dan masuk ke Graveyard.",
    "tutorial.step4.interactiveTaskPrompt": "Serang Surawisesa (DEF 1100) menggunakan Gajah Mada (ATK 1500).",
    "tutorial.step4.actionButtonLabel": "Deklarasikan Serangan (1500 ATK vs 1100 DEF)",
    "tutorial.step4.outcomeFeedback": "Serangan menembus pertahanan! 1500 ATK > 1100 DEF: Surawisesa gugur dari Baris Depan lawan!",
    "tutorial.step5.title": "5. Pertempuran Seimbang / Seri (ATK == DEF)",
    "tutorial.step5.culturalHighlight": "Keseimbangan kekuatan antara dua tokoh besar menghasilkan benturan tanpa korban.",
    "tutorial.step5.ruleExplanation": "Sesuai PRD 8.6, apabila nilai Attack penyerang sama dengan nilai Defence target (ATK A == DEF B), hasil pertempuran adalah Seri: tidak ada kartu yang gugur dan tidak terjadi serangan balik.",
    "tutorial.step5.interactiveTaskPrompt": "Uji benturan seimbang antara Hayam Wuruk (ATK 1200) melawan Sri Baduga Maharaja (DEF 1200 setelah debuff).",
    "tutorial.step5.actionButtonLabel": "Uji Resolusi Seri (1200 ATK == 1200 DEF)",
    "tutorial.step5.outcomeFeedback": "Seri! Kedua pemimpin besar bertahan di Baris Depan masing-masing tanpa ada yang gugur.",
    "tutorial.step6.title": "6. Serangan Gagal (ATK < DEF) & Serangan Balik Otomatis!",
    "tutorial.step6.culturalHighlight": "Menyerang kartu tertutup secara gegabah tanpa perhitungan instrumen dapat berbalik menghancurkan penyerang.",
    "tutorial.step6.ruleExplanation": "Jika Attack penyerang lebih kecil dari Defence lawan (ATK A < DEF B), serangan gagal dan lawan otomatis melakukan Serangan Balik (Counter-Attack)! Dalam serangan balik, giliran Attack B dibandingkan terhadap Defence A (ATK B vs DEF A). Jika ATK B > DEF A, justru penyerang A yang gugur!",
    "tutorial.step6.interactiveTaskPrompt": "Simulasikan risiko menyerang Sri Baduga Maharaja (DEF 1400, ATK 1200) menggunakan Karakter dengan ATK 1100 & DEF 1000.",
    "tutorial.step6.actionButtonLabel": "Simulasikan Serangan Balik Otomatis",
    "tutorial.step6.outcomeFeedback": "Serangan Balik Mematikan! Serangan awal gagal (1100 ATK < 1400 DEF), lalu Sri Baduga membalas dengan 1200 ATK > 1000 DEF penyerang!",
    "tutorial.step7.title": "7. Promosi Baris Kedua & Pengisian Ulang Otomatis",
    "tutorial.step7.culturalHighlight": "Regenerasi kepemimpinan dan kesinambungan barisan menjaga keutuhan kerajaan hingga titik penghabisan.",
    "tutorial.step7.ruleExplanation": "Ketika 1 Karakter di Baris Depan gugur, pemain memilih 1 Karakter dari Baris Kedua (Second Row) untuk naik menggantikan posisi di Baris Depan. Slot Baris Kedua yang kosong kemudian otomatis diisi ulang dari Deck Karakter cadangan. Pemain menang saat seluruh 10 Karakter lawan habis!",
    "tutorial.step7.interactiveTaskPrompt": "Naikkan Tribhuwana Wijayatunggadewi dari Baris Kedua ke Baris Depan.",
    "tutorial.step7.actionButtonLabel": "Promosikan Karakter ke Baris Depan",
    "tutorial.step7.outcomeFeedback": "Promosi berhasil! Tribhuwana kini memimpin di Baris Depan dan slot Baris Kedua otomatis terisi dari Deck Karakter. Anda siap bertempur!",
    "tutorial.step2.sampleInstrumentEffect": "+200 ATK & Abaikan 150 DEF Lawan",
    "tutorial.step3.sampleInstrumentEffect": "+300 ATK (+100 Sinergi Prajurit)",

