    "tour.step.nwjWelcome.title": "Dasbor Ksatria Nusantara",
    "tour.step.nwjWelcome.content": "Ini adalah markas komando Anda. Di sini Anda dapat memantau koleksi kartu, formasi deck yang tersimpan, rasio kemenangan, dan riwayat pertempuran.",
