    // User Tutorial
    "tutorial.stepAriaLabel": "Tutorial Step",
    "tutorial.stepLabelPrefix": "Step",
    "tutorial.culturalHighlightLabel": "Historical & Cultural Context:",
    "tutorial.interactiveExerciseLabel": "Interactive Exercise:",
    "tutorial.boardPreviewTitle": "2-Row Tactical Battlefield Simulation",
    "tutorial.botFrontRow": "Opponent (Bot) Front Row",
    "tutorial.playerFrontRow": "Warrior Front Row",
    "tutorial.playerBackRow": "Warrior Back Row",
    "tutorial.waditraHand": "Waditra Hand",
    "tutorial.step1.title": "1. Two-Row Formation & Face-Down Opponent Cards",
    "tutorial.step1.culturalHighlight": "Inspired by the Wilwatikta (Majapahit) and Pakuan (Pajajaran) battle formations, which separated the main force from reserves.",
    "tutorial.step1.ruleExplanation": "Each player builds a deck with 10 characters and 0 to 10 instruments. At match start, 5 characters enter the board: 2 in the Front Row and 3 in the Second Row, while the other 5 remain in the reserve deck. All opponent cards on the board start face down.",
    "tutorial.step1.interactiveTaskPrompt": "Use the simulation button below to place the first 5 characters in the Front and Second Rows.",
    "tutorial.step1.actionButtonLabel": "Simulate Two-Row Deployment",
    "tutorial.step1.outcomeFeedback": "Success! Raden Wijaya and Gajah Mada guard the Front Row, while Hayam Wuruk, Tribhuwana, and Mpu Prapanca wait in the Second Row.",
    "tutorial.step2.title": "2. Dice Roll, Instrument Draw & Six-Card Hand Limit",
    "tutorial.step2.culturalHighlight": "Waditra (traditional musical instruments) serve as secret command signals on the battlefield.",
    "tutorial.step2.ruleExplanation": "At the start of a match, both players roll 3D dice to determine who goes first and receive 3 starting Instrument cards. At the start of each turn, a player draws 1 Instrument. The hand limit is 6 cards: if it is full, a new card goes straight to the Discard Pile. When the Instrument Deck runs out, the Discard Pile is shuffled automatically.",
    "tutorial.step2.interactiveTaskPrompt": "Simulate drawing an Instrument at the start of a turn.",
    "tutorial.step2.actionButtonLabel": "Draw an Instrument Card",
    "tutorial.step2.outcomeFeedback": "A Kendang Instrument card was drawn into your hidden hand (4/6 cards)!",
    "tutorial.step3.title": "3. Instrument Effects & Affinity Synergy Bonus (+100 Stats)",
    "tutorial.step3.culturalHighlight": "Each Nusantara instrument has a cultural affinity with specific roles (Leader, Warrior, Sage, Envoy, or Artisan).",
    "tutorial.step3.ruleExplanation": "Instruments can be attached to any character on the board for flexible effects. If a character's primary or secondary role and gender match an instrument's affinity, that character also gains a +100 Synergy Bonus to a stat.",
    "tutorial.step3.interactiveTaskPrompt": "Attach Padahi (+300 ATK, Warrior affinity) to Gajah Mada (Role: Warrior).",
    "tutorial.step3.actionButtonLabel": "Activate Padahi on Gajah Mada",
    "tutorial.step3.outcomeFeedback": "Synergy active! Gajah Mada gains +300 base ATK and +100 Warrior Synergy, for +400 ATK total (1900 ATK)!",
    "tutorial.step4.title": "4. Breaking Through Defense (ATK > DEF)",
    "tutorial.step4.culturalHighlight": "Only characters in the Front Row can declare attacks or be attacked.",
    "tutorial.step4.ruleExplanation": "When a Front Row Character A attacks an opposing Front Row Character B, the opponent's face-down card is revealed. If the attacker's Attack is greater than the defender's Defense (ATK A > DEF B), Character B is defeated and sent to the Graveyard.",
    "tutorial.step4.interactiveTaskPrompt": "Attack Surawisesa (1100 DEF) with Gajah Mada (1500 ATK).",
    "tutorial.step4.actionButtonLabel": "Declare Attack (1500 ATK vs 1100 DEF)",
    "tutorial.step4.outcomeFeedback": "The attack breaks through! 1500 ATK > 1100 DEF: Surawisesa is defeated in the opponent's Front Row.",
    "tutorial.step5.title": "5. Balanced Combat / Tie (ATK == DEF)",
    "tutorial.step5.culturalHighlight": "When two great figures are evenly matched, their clash ends without casualties.",
    "tutorial.step5.ruleExplanation": "Under PRD 8.6, when the attacker's Attack equals the target's Defense (ATK A == DEF B), the result is a tie: neither card is defeated and no counterattack occurs.",
    "tutorial.step5.interactiveTaskPrompt": "Test an even clash: Hayam Wuruk (1200 ATK) against Sri Baduga Maharaja (1200 DEF after a debuff).",
    "tutorial.step5.actionButtonLabel": "Test Tie Resolution (1200 ATK == 1200 DEF)",
    "tutorial.step5.outcomeFeedback": "Tie! Both leaders remain in their Front Rows without being defeated.",
    "tutorial.step6.title": "6. Failed Attack (ATK < DEF) & Automatic Counterattack!",
    "tutorial.step6.culturalHighlight": "Carelessly attacking a face-down card without calculating instrument effects can turn the attack against you.",
    "tutorial.step6.ruleExplanation": "If the attacker's Attack is lower than the opponent's Defense (ATK A < DEF B), the attack fails and the opponent counterattacks automatically. The counterattack compares B's Attack against A's Defense (ATK B vs DEF A). If ATK B > DEF A, attacker A is defeated.",
    "tutorial.step6.interactiveTaskPrompt": "Simulate attacking Sri Baduga Maharaja (1400 DEF, 1200 ATK) with a character at 1100 ATK and 1000 DEF.",
    "tutorial.step6.actionButtonLabel": "Simulate Automatic Counterattack",
    "tutorial.step6.outcomeFeedback": "Devastating counterattack! The first attack fails (1100 ATK < 1400 DEF), then Sri Baduga retaliates with 1200 ATK > the attacker's 1000 DEF.",
    "tutorial.step7.title": "7. Second-Row Promotion & Automatic Refill",
    "tutorial.step7.culturalHighlight": "Leadership succession and continuous ranks preserve the kingdom's strength until the end.",
    "tutorial.step7.ruleExplanation": "When a Front Row character is defeated, the player chooses a character from the Second Row to take its place. The empty Second Row slot is then refilled automatically from the reserve Character Deck. A player wins when all 10 opposing characters are defeated.",
    "tutorial.step7.interactiveTaskPrompt": "Promote Tribhuwana Wijayatunggadewi from the Second Row to the Front Row.",
    "tutorial.step7.actionButtonLabel": "Promote Character to Front Row",
    "tutorial.step7.outcomeFeedback": "Promotion successful! Tribhuwana now leads the Front Row, and the empty Second Row slot is refilled from the Character Deck. You are ready to fight!",
    "tutorial.step2.sampleInstrumentEffect": "+200 ATK & Ignore 150 enemy DEF",
    "tutorial.step3.sampleInstrumentEffect": "+300 ATK (+100 Warrior Synergy)",

