    // User Tutorial
    "tutorial.stepAriaLabel": "教程步骤",
    "tutorial.stepLabelPrefix": "步骤",
    "tutorial.culturalHighlightLabel": "历史与文化背景：",
    "tutorial.interactiveExerciseLabel": "互动演练：",
    "tutorial.boardPreviewTitle": "2 行战术战场模拟",
    "tutorial.botFrontRow": "对手 (Bot) 前排",
    "tutorial.playerFrontRow": "我方前排",
    "tutorial.playerBackRow": "我方后排",
    "tutorial.waditraHand": "手牌乐器",
    "tutorial.step1.title": "1. 双排阵型与背面朝上的敌方卡牌",
    "tutorial.step1.culturalHighlight": "灵感来自 Wilwatikta（满者伯夷）与 Pakuan（巴查查兰）的布阵方式，将主力与预备队分开部署。",
    "tutorial.step1.ruleExplanation": "每位玩家组建一套包含 10 张角色卡和 0 至 10 件乐器的套牌。对局开始时，5 张角色卡进入棋盘：2 张位于前排，3 张位于次排，其余 5 张留在预备套牌中。对手在棋盘上的卡牌初始均为背面朝上。",
    "tutorial.step1.interactiveTaskPrompt": "点击下方模拟按钮，将首批 5 张角色卡放入前排和次排。",
    "tutorial.step1.actionButtonLabel": "模拟部署双排阵型",
    "tutorial.step1.outcomeFeedback": "成功！Raden Wijaya 和 Gajah Mada 镇守前排，Hayam Wuruk、Tribhuwana 与 Mpu Prapanca 在次排待命。",
    "tutorial.step2.title": "2. 掷骰、抽取乐器与六张手牌上限",
    "tutorial.step2.culturalHighlight": "Waditra（传统乐器）在战场上充当秘密指挥信号。",
    "tutorial.step2.ruleExplanation": "对局开始时，双方掷 3D 骰子决定先手，并各自获得 3 张初始乐器卡。每回合开始时，玩家抽取 1 张乐器卡。手牌上限为 6 张；手牌已满时，新卡会直接进入弃牌堆。乐器套牌耗尽后，弃牌堆会自动洗回套牌。",
    "tutorial.step2.interactiveTaskPrompt": "模拟在回合开始时抽取一张乐器卡。",
    "tutorial.step2.actionButtonLabel": "抽取乐器卡",
    "tutorial.step2.outcomeFeedback": "Kendang 乐器卡已抽入您的隐藏手牌（当前 4/6 张）！",
    "tutorial.step3.title": "3. 乐器效果与属性共鸣加成（+100）",
    "tutorial.step3.culturalHighlight": "每件努山塔拉乐器都与特定角色文化相关，例如领袖、战士、学者、使者或工匠。",
    "tutorial.step3.ruleExplanation": "乐器可以装备给棋盘上的任意角色，灵活触发效果。如果角色的主要或次要身份及性别符合乐器共鸣条件，该角色还会获得 +100 属性共鸣加成。",
    "tutorial.step3.interactiveTaskPrompt": "将 Padahi（+300 ATK，战士共鸣）装备给 Gajah Mada（身份：战士）。",
    "tutorial.step3.actionButtonLabel": "为 Gajah Mada 启用 Padahi",
    "tutorial.step3.outcomeFeedback": "共鸣已触发！Gajah Mada 获得 +300 基础 ATK 与 +100 战士共鸣，总计增加 +400 ATK（达到 1900）！",
    "tutorial.step4.title": "4. 突破防御（ATK > DEF）",
    "tutorial.step4.culturalHighlight": "只有前排角色可以发起攻击或成为攻击目标。",
    "tutorial.step4.ruleExplanation": "前排角色 A 攻击敌方前排角色 B 时，敌方背面朝上的卡牌会翻开。如果攻击者的攻击力高于防守者的防御力（ATK A > DEF B），角色 B 会被击败并进入墓地。",
    "tutorial.step4.interactiveTaskPrompt": "使用 Gajah Mada（1500 ATK）攻击 Surawisesa（1100 DEF）。",
    "tutorial.step4.actionButtonLabel": "发起攻击（1500 ATK 对 1100 DEF）",
    "tutorial.step4.outcomeFeedback": "攻击突破防线！1500 ATK > 1100 DEF：Surawisesa 在敌方前排被击败！",
    "tutorial.step5.title": "5. 势均力敌 / 平局（ATK == DEF）",
    "tutorial.step5.culturalHighlight": "两位强者势均力敌时，交锋不会造成伤亡。",
    "tutorial.step5.ruleExplanation": "依据 PRD 8.6，当攻击者的攻击力等于目标的防御力（ATK A == DEF B）时，结果为平局：双方卡牌均不会被击败，也不会触发反击。",
    "tutorial.step5.interactiveTaskPrompt": "测试势均力敌的交锋：Hayam Wuruk（1200 ATK）对抗 Sri Baduga Maharaja（减益后 1200 DEF）。",
    "tutorial.step5.actionButtonLabel": "测试平局判定（1200 ATK == 1200 DEF）",
    "tutorial.step5.outcomeFeedback": "平局！两位领袖都留在各自前排，没有角色被击败。",
    "tutorial.step6.title": "6. 攻击失败（ATK < DEF）与自动反击！",
    "tutorial.step6.culturalHighlight": "未计算乐器效果就贸然攻击背面朝上的卡牌，可能让攻击反噬自身。",
    "tutorial.step6.ruleExplanation": "若攻击者的攻击力低于敌方防御力（ATK A < DEF B），攻击会失败，敌方自动反击。反击时比较 B 的攻击力与 A 的防御力（ATK B 对 DEF A）。若 ATK B > DEF A，攻击者 A 会被击败。",
    "tutorial.step6.interactiveTaskPrompt": "模拟使用 1100 ATK、1000 DEF 的角色攻击 Sri Baduga Maharaja（1400 DEF、1200 ATK）。",
    "tutorial.step6.actionButtonLabel": "模拟自动反击",
    "tutorial.step6.outcomeFeedback": "反击致命！首次攻击失败（1100 ATK < 1400 DEF），随后 Sri Baduga 以 1200 ATK 反击，超过攻击者的 1000 DEF。",
    "tutorial.step7.title": "7. 次排晋升与自动补位",
    "tutorial.step7.culturalHighlight": "领袖接替与阵列延续能让王国坚持到最后。",
    "tutorial.step7.ruleExplanation": "前排角色被击败后，玩家可从次排选择一名角色接替前排位置。空出的次排位置会从预备角色套牌自动补位。击败敌方全部 10 名角色即可获胜。",
    "tutorial.step7.interactiveTaskPrompt": "将 Tribhuwana Wijayatunggadewi 从次排晋升至前排。",
    "tutorial.step7.actionButtonLabel": "将角色晋升至前排",
    "tutorial.step7.outcomeFeedback": "晋升成功！Tribhuwana 已领队前排，次排空位也已从角色套牌自动补齐。准备迎战！",
    "tutorial.step2.sampleInstrumentEffect": "+200 ATK 并忽略敌方 150 DEF",
    "tutorial.step3.sampleInstrumentEffect": "+300 ATK（+100 战士共鸣）",

