export const translator = {
  t(
    key: string,
    locale: SupportedLocale = DEFAULT_LOCALE,
    values?: TranslationValues
  ): string {
    if (key.startsWith("server.message.") || key.startsWith("server.card.") || key.startsWith("server.shop.") || key.startsWith("api.error.")) {
      return localizeMessageKey(key, values, locale, key);
    }
    const dict = DICTIONARIES[locale] ?? DICTIONARIES[DEFAULT_LOCALE];
    const template = dict[key] ?? DICTIONARIES[DEFAULT_LOCALE][key] ?? key;
    if (!values) return template;
    return template.replace(/\{([a-zA-Z0-9_]+)\}/g, (placeholder, name: string) =>
      Object.prototype.hasOwnProperty.call(values, name)
        ? String(values[name])
        : placeholder
    );
  },
  getDictionary(
    locale: SupportedLocale = DEFAULT_LOCALE
  ): Record<string, string> {
    return DICTIONARIES[locale] ?? DICTIONARIES[DEFAULT_LOCALE];
  },
} as const;
